package main

import (
	_ "embed"
	"encoding/base64"
	"fmt"
	"maps"
	"slices"
	"strings"

	"github.com/spf13/cobra"
	tinkpb "github.com/tink-crypto/tink-go/v2/proto/tink_go_proto"
	"google.golang.org/protobuf/proto"
)

// javaKeyTemplates holds every key template of Java Tinkey 1.14.0, one per
// line, as "NAME base64(serialized KeyTemplate proto)". It is generated by
// `make java-key-templates`; never edit it by hand.
//
//go:embed java_key_templates.txt
var javaKeyTemplates string

// aesEAXTypeURL is the one key type of Java Tinkey that tink-go cannot
// generate, so its templates are left out of keyTemplates.
const aesEAXTypeURL = "type.googleapis.com/google.crypto.tink.AesEaxKey"

// keyTemplates maps the --key-template names to the templates of new keys.
// Names and templates are the ones of Java Tinkey, so that a key made here has
// the same parameters as the key Java Tinkey makes for the same name.
var keyTemplates = parseJavaKeyTemplates()

func parseJavaKeyTemplates() map[string]*tinkpb.KeyTemplate {
	templates := make(map[string]*tinkpb.KeyTemplate)
	for line := range strings.Lines(javaKeyTemplates) {
		// A malformed line is a broken generated file: a programming error.
		name, encoded, hasTwoFields := strings.Cut(strings.TrimSpace(line), " ")
		if !hasTwoFields {
			panic(fmt.Sprintf("java_key_templates.txt: malformed line %q", line))
		}
		serialized, err := base64.StdEncoding.DecodeString(encoded)
		if err != nil {
			panic(fmt.Sprintf("java_key_templates.txt: key template %s: %v", name, err))
		}
		template := &tinkpb.KeyTemplate{}
		if err := proto.Unmarshal(serialized, template); err != nil {
			panic(fmt.Sprintf("java_key_templates.txt: key template %s: %v", name, err))
		}
		if template.GetTypeUrl() == aesEAXTypeURL {
			continue
		}
		templates[name] = template
	}
	return templates
}

func lookupKeyTemplate(name string) (*tinkpb.KeyTemplate, error) {
	template, isSupported := keyTemplates[name]
	if !isSupported {
		return nil, fmt.Errorf("unknown key template %q: run list-key-templates to get supported names", name)
	}
	return template, nil
}

// addKeyTemplateFlag defines the required --key-template flag on cmd.
func addKeyTemplateFlag(cmd *cobra.Command, keyTemplateName *string) {
	cmd.Flags().StringVar(keyTemplateName, "key-template", "",
		"The key template name. Run list-key-templates to get supported names")
	requireFlag(cmd, "key-template")
}

// requireFlag marks a flag already defined on cmd as required.
func requireFlag(cmd *cobra.Command, name string) {
	if err := cmd.MarkFlagRequired(name); err != nil {
		// Only fails when the flag is not defined on cmd: a programming error.
		panic(err)
	}
}

func newListKeyTemplatesCommand() *cobra.Command {
	return &cobra.Command{
		Use:   "list-key-templates",
		Short: "Lists all supported key templates",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			names := slices.Sorted(maps.Keys(keyTemplates))
			_, err := fmt.Fprintf(cmd.OutOrStdout(), "The following key templates are supported:\n%s\n",
				strings.Join(names, "\n"))
			return err
		},
	}
}
